modeling/T6/scripts/t6_mod009_hybrid_lex.build_text:
def build_text(
    df: pd.DataFrame,
    fields: list[str],
) -> pd.Series:
    return (
        df[fields]
        .fillna("")
        .astype(str)
        .agg(" ".join, axis=1)
        .str.replace(r"\s+", " ", regex=True)
        .str.strip()
    )

