modeling/T6/scripts/t6_mod010_exact_tfid.build_text:
def build_text(
    frame: pd.DataFrame,
    columns: list[str],
) -> pd.Series:

    parts = []

    for column in columns:

        field_name = column.replace(
            "_",
            " ",
        )

        values = frame[column].map(
            clean_text
        )

        parts.append(
            field_name
            + " "
            + values
        )

    result = parts[0]

    for part in parts[1:]:

        result = (
            result
            + " "
            + part
        )

    return result
